"""All held-out outcomes with class service checks and BC/PPO distinction."""
import json,statistics,datetime
from pathlib import Path
H=Path(__file__).resolve().parent;R=H.parents[1];O=H/'artifacts/G001'
def read(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def write(p,x):
    with Path(p).open('x',encoding='utf-8') as f:json.dump(x,f,ensure_ascii=False,allow_nan=False,indent=2)
def mean(xs):return statistics.mean(xs) if xs else None
result=read(O/'RESULT.json');selection=read(O/'SELECTION_FROZEN.json');bc=read(O/'BC_TRAINING.json');rows=[r for r in result['rows'] if r['kind']=='EVAL'];pm=read(R/'experiments/capacity_power_v1/artifacts/G001/MODEL.json');gamma=pm['coef'][2]/pm['scale'][2]
edf={r['input']:r for r in rows if r['mode']=='EDF_GPU_FIRST'};old={r['input']:r for r in rows if r['seed']==481083};warm={r['input']:r for r in rows if r['seed']==881000}
def method(r):return 'OLD_RL' if r['seed']==481083 else 'OLD_EVENT_RL' if r['seed']==781081 else 'BC_FROZEN' if r['seed']==881000 else 'EVENT_PPO' if r['seed'] is not None else r['mode']
def nonharm(a,b):return a['unfinished']==b['unfinished']==0 and all(a['service'][k]['on_time']>=b['service'][k]['on_time'] for k in ['all','urgent','normal'])
groups=[]
for load in [.65,.85]:
    for m in ['EDF_GPU_FIRST','ATC','ATC_SALVAGE','OLD_RL','OLD_EVENT_RL','BC_FROZEN','EVENT_PPO','DEV_SELECTED_EVENT_PPO']:
        rr=[r for r in rows if r['load']==load and (r['seed']==selection['selected'] if m=='DEV_SELECTED_EVENT_PPO' else method(r)==m)];bb=[edf[r['input']] for r in rr];oo=[old[r['input']] for r in rr];ww=[warm[r['input']] for r in rr]
        J=mean([r['J'] for r in rr]);T=mean([r['AP_mean'] for r in rr]);dJ=J-mean([b['J'] for b in bb]);dcore=mean([r['extra_CPU_core_s'] for r in rr])-mean([b['extra_CPU_core_s'] for b in bb])
        groups.append(dict(load=load,method=m,rows=len(rr),on_percent=100*mean([r['service']['all']['on_time']/r['n'] for r in rr]),urgent_percent=100*mean([r['service']['urgent']['on_time']/r['service']['urgent']['planned'] for r in rr]),normal_percent=100*mean([r['service']['normal']['on_time']/r['service']['normal']['planned'] for r in rr]),mean_API_J=J,EDF_energy_delta_percent=100*(J/mean([b['J'] for b in bb])-1),OLD_RL_energy_delta_percent=100*(J/mean([b['J'] for b in oo])-1),BC_energy_delta_percent=100*(J/mean([b['J'] for b in ww])-1),mean_AP_C=T,EDF_AP_delta_C=T-mean([b['AP_mean'] for b in bb]),BC_AP_delta_C=T-mean([b['AP_mean'] for b in ww]),max_sampled_AP_C=max(r['AP_peak'] for r in rr),mean_case_P95_s=mean([r['service']['all']['p95_s'] for r in rr]),unfinished=sum(r['unfinished'] for r in rr),EDF_nonharm_pairs=sum(nonharm(r,b) for r,b in zip(rr,bb)),OLD_RL_nonharm_pairs=sum(nonharm(r,b) for r,b in zip(rr,oo)),BC_nonharm_pairs=sum(nonharm(r,b) for r,b in zip(rr,ww)),outside_AP_rows=sum(r['outside_AP'] for r in rr),mean_extra_CPU_core_s=mean([r['extra_CPU_core_s'] for r in rr]),EDF_energy_delta_with_CPU_proxy_charge_percent=100*(mean([r['J']+gamma*r['extra_CPU_core_s'] for r in rr])/mean([b['J']+gamma*b['extra_CPU_core_s'] for b in bb])-1),break_even_extra_core_API_W=(-dJ/dcore if dcore>1e-9 else None),seed_on_percent={str(seed):100*mean([r['service']['all']['on_time']/r['n'] for r in rr if r['seed']==seed]) for seed in sorted(set(r['seed'] for r in rr if r['seed'] is not None))}))
summary=dict(status='GROUP_ROUTE_ALL72_FRESH_EVALUATIONS_SUMMARIZED',utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),START=result['START'],COMPLETE=result['COMPLETE'],FAIL=result['FAIL'],PPO_updates=3,BC_epochs=len(bc['logs']),BC_accuracy=bc['logs'][-1]['TRAIN_demonstration_accuracy'],BC_compatible_accuracy=bc['logs'][-1]['TRAIN_compatible_accuracy'],BC_group_accuracy=bc['logs'][-1]['TRAIN_group_accuracy'],BC_steps=bc['steps'],selected=selection['selected'],groups=groups,rows=rows,physical_validation=False,no_deadline_protection=True,CPU_scenario='CPU3 nonzero service work; logical route slots1 each, added core power unknown',CPU_proxy_surcharge_API_W=gamma)
write(O/'COMPARISON_SUMMARY.json',summary)
names={'EDF_GPU_FIRST':'단순 EDF','ATC':'ATC','ATC_SALVAGE':'보완 ATC','OLD_RL':'기존 RL 고정','OLD_EVENT_RL':'앞 사건 RL 고정','BC_FROZEN':'교사학습 후 고정(PPO 전)','EVENT_PPO':'사건 기반 보완 RL 3seed 평균','DEV_SELECTED_EVENT_PPO':'DEV 선정 보완 RL'}
lines=['# S26 희소 경로 학습·공개 후보순위 보완 RL 결과','',f"START{result['START']} / COMPLETE{result['COMPLETE']} / FAIL{result['FAIL']}. 저장 TRAIN 참조8·규칙 시연4 재사용(새 실행0)·PPO 학습6·DEV36·새 EVAL72, 실제 PPO update3. 교사학습은 {len(bc['logs'])}epoch/{bc['steps']}step, TRAIN 시연 일치율 {summary['BC_accuracy']:.3%}다. 시연 일치율은 평가 성능이 아니다.",'','## 같은 CPU3 가정·같은 입력의 전체 비교','', '|명목부하|방식|정시율|긴급/일반 정시율|전체API-J|대EDF 소비|평균AP|대EDF 평균AP|최고AP표본|세션P95 평균|미AVAILABLE|','|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
lines.insert(3,'TRAIN 호환정답 일치율 '+format(summary['BC_compatible_accuracy'],'.3%')+'·행동/경로군별 '+str(summary['BC_group_accuracy'])+'다. 같은 공개 EDF 기한·같은 경로의 동률 요청은 학습 목표 확률을 합산했다. 이는 평가 정시율이나 서로 다른 잠재 실행의 물리적 동일성을 보증하지 않는다.')
for g in groups:lines.append(f"|{g['load']:.0%}|{names[g['method']]}|{g['on_percent']:.3f}%|{g['urgent_percent']:.3f}/{g['normal_percent']:.3f}%|{g['mean_API_J']:.3f}|{g['EDF_energy_delta_percent']:+.3f}%|{g['mean_AP_C']:.3f}℃|{g['EDF_AP_delta_C']:+.3f}℃|{g['max_sampled_AP_C']:.3f}℃|{g['mean_case_P95_s']:.3f}s|{g['unfinished']}|")
lines+=['','긴급/일반 정시율과 P95는 세션별 값의 평균이다. 85%는 원 입력의 명목 부하이고 CPU3의 실측 이용률85%를 뜻하지 않는다. 각 부하는 N1024·분류50/75%·서로 다른 잠재 phase/template 스트림2개씩이다. 같은 burst16 도착 패턴을 유지한 모형 평가이며 독립 실기기 반복측정이 아니다. 모든 seed를 보고하고 대표 seed는 DEV에서 고정했다. 에너지 감소율은 표의 평균 에너지끼리 계산한다. 평균AP는35초부터 관측 종료까지 세션 시간평균을 평균한 값이고 최고는 모든 세션의 최대 표본이다. 유휴·냉각을 포함하며 최고값이 연속시간의 수학적 최대라는 보증은 없다.','', '## 서비스 보존과 추가 CPU 소비 감도','', '|부하|방식|대EDF 전군 비악화 쌍|대기존RL 전군 비악화 쌍|교사학습 고정 대비 소비|추가코어 계수 부과시 대EDF 소비|','|---|---|---:|---:|---:|---:|']
for g in groups:
    if g['method'] in ['BC_FROZEN','EVENT_PPO','DEV_SELECTED_EVENT_PPO']:lines.append(f"|{g['load']:.0%}|{names[g['method']]}|{g['EDF_nonharm_pairs']}/{g['rows']}|{g['OLD_RL_nonharm_pairs']}/{g['rows']}|{g['BC_energy_delta_percent']:+.3f}%|{g['EDF_energy_delta_with_CPU_proxy_charge_percent']:+.3f}%|")
lines+=['','같은 입력에서 전량AVAILABLE이고 전체·긴급·일반 정시율이 모두 낮아지지 않은 경우만 전군 비악화다. 평균 개선과 모든 입력의 비악화는 다르다. 교사학습 고정과 비교해 PPO의 추가 기여를 따로 판단하며, 규칙을 배운 성과 전체를 RL만의 기여로 부르지 않는다.','', '## 보완한 구조','', '기존 예측은 첫 후보 뒤의 가상 배정에서 EDF/최속 경로를 사용했다. 보완판은 실제로 관측한 최근64 요청의 작업종류와 경로 선호를 후속 가상 배정에도 반영한다. 처음16개 관측 전에는 보수적인75% 분류 가정을 쓰고, 관측 분류 비중62.5% 이하는NPU 선호, 그 이상은 관측 분류 카운터4개 중1개를GPU로 선호한다. 탐지는CPU다. 선호는 NN 입력과 명목 예측의 정보이며 실제 NN의 다른 합법 경로를 제거하지 않는다. 기한 충족 여부로 후보를 거르지 않는다.','', 'WAIT_EVENT는 이미 실행 중인 작업이 AVAILABLE이 되거나 새 요청이 ready가 될 때 깨운다. 정책에 실제 미래 이벤트 시각을 주지 않으며 예측에서는 명목 작업의 완료만 계산한다. 임의의50ms 반복 대기보다 슬롯 반환에 맞춰 다시 결정할 수 있다. 고정20/50ms 대기도 남기고 임박 요청 강제·납기mask·고정logit prior·NN 뒤 규칙교체는0이다. 실제 마지막 행동은 NN logits가 선택한다.','', '저장 TRAIN 시연의 입력만 공개 후보 EDF/FIFO 순위로 다시 부호화했다(새 환경 실행0). DISPATCH의 기존 항상0이던30번 입력에 현재 후보 순위를 제공하고 WAIT 시간 입력은 유지했다. 이는 동률을 구별할 정보이며 납기 가능성으로 후보를 제거하지 않는다. 앞 사건 RL 고정 대조에는 이 새 입력을 적용하지 않았다. TRAIN 규칙 시연으로 경로별 역빈도 가중치와 동일 EDF 동률 행동의 합산 확률로 공통 actor를 최대64epoch 학습한 뒤3개 PPO seed를 같은 가중치에서 시작했다. critic/Adam/RNG는 새로 설정했고 각 seed N512·85% 두 배합2episode/1update, LR0.0001·KL중단·샘플링온도0.35를 사용했다. 에너지/열은 TRAIN 참조로 정규화하고 지연은 군별 분모·0.02 추가지각항을 사용한다. 목적별 actor advantage RMS 정규화와 soft dual 납기 벌점을 적용했다. 보상·표현·예측·대기·초기화를 함께 바꾼 묶음검증이며 각 요소의 독립 인과효과를 분리하지 않는다.','', '## 물리와 해석의 한계','', '모든 비교는 CPU 서비스 최대3개 병렬 가정이다. CPU 작업량을 삭제하지 않았고 CPU/GPU/NPU route 슬롯은 각각1개·비선점·AVAILABLE 예약을 유지한다. 실제S26의3개 서비스 동시처리·추가 코어 소비·미측정 pair/triple 간섭은 검증되지 않았다. 추가 코어 가동시간에 기존 CPU union 계수 '+f'{gamma:.6f}'+' API-W/core를 부과한 감도도 보고했다. 실제 한계전력/신뢰구간/안전상한이라는 뜻이 아니며 그 감도는 저장 스케줄의 에너지 계산으로 온도·속도 피드백 재실행이 아니다.','', 'API-J는 외부 전력계로 보정하지 않은 전력 후보의 전체 관측창 적분이다. AP는 센서 예측이다. 기존 전력/열 정확도gate FAIL은 유지하며26~46.6℃ 밖은 외삽이다. 현재 M8 온도자료 최대211.682초·256초 이후0세션인 자료 한계도 유지한다. 새 기기측정·물리 fit·임의 온도clamp·만들어낸 스로틀링·업로드0이다. 기기의 예측/NN/제어 비용은 미측정이고 PC 소요시간을 휴대전화 비용으로 넣지 않았다.','', '[전수 수치](experiments/route_group_learning_v1/artifacts/G001/COMPARISON_SUMMARY.json) · [등록](experiments/route_group_learning_v1/PROTOCOL.json) · [저장 검산](experiments/route_group_learning_v1/artifacts/G001/AUDIT.json) · [BC/PPO 재검산](experiments/route_group_learning_v1/artifacts/G001/NN_AUDIT.json) · [앞 단계 사건 RL 결과](S26_ROUTE_EVENT_RESULTS_KO.md) · [고정 경로 대조](S26_ROUTE_WITNESS_RESULTS_KO.md)']
with (R/'S26_ROUTE_GROUP_RESULTS_KO.md').open('x',encoding='utf-8') as f:f.write('\n'.join(lines)+'\n')
